// Consolida config_execucao.json + cobrancas.json + apelidos.json (binário -> JSON)
// e embute os 3 perfis de projeto (cópia de /profiles/*.json — seção 6 do spec.md).
// Perfis embutidos aqui (não buscados via HTTP), por decisão já confirmada.

function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return {};
  const buffer = Buffer.from(item.binary.data.data, 'base64');
  return JSON.parse(buffer.toString('utf8'));
}

const config = parseBinaryJson($('Ler config_execucao.json').first());
const cobrancas = parseBinaryJson($('Ler cobrancas.json').first());
const apelidos = parseBinaryJson($('Ler apelidos.json').first());

const perfis = {
  AREP: {
    projeto: 'AREP (S01 antigo)',
    prefixo_assunto_pedido: 'AREP | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'AREP | NOTAS À PAGAR',
    texto_ref: 'SMTC',
    retranca: 'S01',
  },
  REUNION: {
    projeto: 'Reunion (S01)',
    prefixo_assunto_pedido: 'SMTC - S01 | REUNION | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'SMTC - S01 | REUNION | NOTAS À PAGAR',
    texto_ref: 'SMTC - REUNION',
    retranca: 'REUNION_S01',
  },
  SOFT_PRE: {
    projeto: 'Soft Pré (S02)',
    prefixo_assunto_pedido: 'SMTC - S02 | SOFT PRE | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'SMTC - S02 | SOFT PRE | NOTAS À PAGAR',
    texto_ref: 'SMTC - SOFT PRE',
    retranca: 'SOFT PRE_S02',
  },
};

return [{ json: { config, cobrancas, apelidos, perfis, dominioEmpresa: 'novorealitybox.com' } }];

// Requer NODE_FUNCTION_ALLOW_EXTERNAL=exceljs configurado na VM (spec.md seção 5, decisão técnica).
const ExcelJS = require('exceljs');

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function linhaTemPreenchimento(cell) {
  const fill = cell && cell.fill;
  if (!fill || fill.type !== 'pattern' || fill.pattern !== 'solid') return false;
  const argb = fill.fgColor && fill.fgColor.argb;
  if (!argb) return false;
  return argb !== 'FFFFFFFF' && argb !== '00000000';
}

async function lerAbaNotas(binaryPropertyName, nodeName, projetoFixo) {
  const item = $(nodeName).first();
  const buffer = Buffer.from(item.binary.data.data, 'base64');
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const ws = wb.getWorksheet('Notas') || wb.worksheets[0];
  const linhas = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return; // cabeçalho
    const projetoId = projetoFixo || (linhaTemPreenchimento(row.getCell('L')) ? 'REUNION' : 'AREP');
    linhas.push({
      linha: rowNumber,
      projetoId,
      colunaB: row.getCell('B').text,
      colunaC: row.getCell('C').text,
      colunaG: row.getCell('G').text,
      colunaH: row.getCell('H').text,
      colunaJ: row.getCell('J').text,
      colunaK: Number(row.getCell('K').value) || 0,
      colunaL: row.getCell('L').text,
      colunaN: row.getCell('N').text,
      colunaR: row.getCell('R').text,
    });
  });
  return linhas;
}

async function lerPlanilhaContratos(nodeName) {
  const item = $(nodeName).first();
  const buffer = Buffer.from(item.binary.data.data, 'base64');
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const ws = wb.worksheets[0];
  const linhas = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return;
    linhas.push({
      razaoSocial: row.getCell('A').text,
      nomeColaborador: row.getCell('B').text,
      status: row.getCell('C').text,
    });
  });
  return linhas;
}

const linhasS01 = await lerAbaNotas(null, 'Box — Download Cost Report S01', null); // cor decide AREP/REUNION
const linhasS02 = await lerAbaNotas(null, 'Box — Download Cost Report S02 (Soft Pré)', 'SOFT_PRE');

const contratos = {
  AREP: await lerPlanilhaContratos('Box — Download Contratos AREP'),
  REUNION: await lerPlanilhaContratos('Box — Download Contratos Reunion'),
  SOFT_PRE: await lerPlanilhaContratos('Box — Download Contratos Soft Pré'),
};

const cfg = $('Carregar config + perfis').first().json;

const todasAsLinhas = [...linhasS01, ...linhasS02];

return todasAsLinhas.map((nota) => ({
  json: {
    nota,
    contratosDoProjeto: contratos[nota.projetoId],
    config: cfg.config,
    cobrancas: cfg.cobrancas,
    apelidos: cfg.apelidos,
    perfil: cfg.perfis[nota.projetoId],
    dominioEmpresa: cfg.dominioEmpresa,
  },
}));

// Filtra só as linhas relevantes pra esta execução: candidatas a NOVO PEDIDO
// (Status Box = 'PROGRAMAR ATÉ [data]' ou variante de 'SOLICITAR') ou
// candidatas a MONITORAMENTO/COBRANÇA (Status Box = 'SOLICITADA MI').
// Linhas em qualquer outro estado (RECEBIDA MI, ENTREGUE, etc.) são ignoradas
// nesta fase — seção 3.1/3.1.1 do spec.md.

function ehVarianteSolicitar(statusBox) {
  return /^SOLICITAR/i.test((statusBox || '').trim());
}

function extrairDataProgramarAte(statusBox, anoReferencia) {
  const m = /PROGRAMAR AT[ÉE]\s+(\d{1,2})[\/.](\d{1,2})(?:[\/.](\d{2,4}))?/i.exec(statusBox || '');
  if (!m) return null;
  const dia = parseInt(m[1], 10);
  const mes = parseInt(m[2], 10) - 1;
  const ano = m[3] ? (m[3].length === 2 ? 2000 + parseInt(m[3], 10) : parseInt(m[3], 10)) : anoReferencia;
  return new Date(ano, mes, dia);
}

const hoje = new Date();
const saida = [];

for (const item of $input.all()) {
  const { nota } = item.json;
  const dataProgramarAte = extrairDataProgramarAte(nota.colunaL, hoje.getFullYear());

  if (dataProgramarAte) {
    saida.push({ json: { ...item.json, fluxo: 'novo_pedido', gatilho: 'PROGRAMAR_ATE', dataProgramarAte: dataProgramarAte.toISOString() } });
  } else if (ehVarianteSolicitar(nota.colunaL)) {
    saida.push({ json: { ...item.json, fluxo: 'novo_pedido', gatilho: 'SOLICITAR' } });
  } else if (normalizarSimples(nota.colunaL) === 'solicitada mi') {
    saida.push({ json: { ...item.json, fluxo: 'monitoramento' } });
  }
  // demais status: ignorados nesta fase.
}

function normalizarSimples(t) { return (t || '').toLowerCase().trim(); }

return saida;

// Checagem de contrato — etapa 1 (seção 3.1). Só roda pra fluxo='novo_pedido';
// itens de fluxo='monitoramento' passam direto.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function classificarStatusContrato(statusContrato) {
  const norm = normalizar(statusContrato);
  if (norm.includes('assinado')) return 'ASSINADO';
  return 'PENDENTE_VAZIO';
}

function cruzarComPlanilhaContratos(nota, linhasContratos) {
  const alvoRazao = normalizar(nota.colunaH);
  const partes = (nota.colunaJ || '').split(' - ');
  const alvoNome = normalizar(partes.length >= 2 ? partes[1] : nota.colunaH);
  const encontrada = (linhasContratos || []).find((linha) => {
    const razao = normalizar(linha.razaoSocial);
    const nome = normalizar(linha.nomeColaborador);
    return (alvoRazao && razao === alvoRazao) || (alvoNome && nome === alvoNome);
  });
  if (!encontrada) return { liberado: false };
  return { liberado: classificarStatusContrato(encontrada.status) === 'ASSINADO' };
}

return $input.all().map((item) => {
  const { nota, contratosDoProjeto, fluxo } = item.json;
  if (fluxo !== 'novo_pedido') return item; // monitoramento passa direto

  const statusN = classificarStatusContrato(nota.colunaN);
  if (statusN === 'ASSINADO') {
    return { json: { ...item.json, liberado: true, precisaBuscarFichaCadastral: false, motivoLiberacao: 'coluna_n' } };
  }
  const cruzamento = cruzarComPlanilhaContratos(nota, contratosDoProjeto);
  if (cruzamento.liberado) {
    return { json: { ...item.json, liberado: true, precisaBuscarFichaCadastral: false, motivoLiberacao: 'planilha_contratos' } };
  }
  return { json: { ...item.json, liberado: false, precisaBuscarFichaCadastral: true } };
});

// Checagem de contrato — etapa 2: valida a ficha cadastral a partir das
// mensagens da thread encontrada (critério corrigido — spec.md commit 8a06d6b):
// mensagem de remetente FORA do domínio da empresa, com >=1 anexo.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

function validarFichaCadastral(mensagens, dominioEmpresa) {
  const dominioNorm = normalizar(dominioEmpresa);
  return (mensagens || []).some((msg) => {
    const from = (msg.from || (msg.headers && msg.headers.from) || '');
    const dominioRemetente = normalizar((from.split('@')[1] || '').replace('>', ''));
    const externo = dominioRemetente !== '' && dominioRemetente !== dominioNorm;
    const temAnexo = !!(msg.hasAttachment || (msg.payload && msg.payload.parts && msg.payload.parts.some((p) => p.filename)));
    return externo && temAnexo;
  });
}

const mensagens = $input.all().map((i) => i.json);
const primeiro = $input.first();
const dominioEmpresa = primeiro.json.dominioEmpresa || 'novorealitybox.com';
const validada = validarFichaCadastral(mensagens, dominioEmpresa);

return [{
  json: {
    ...primeiro.json,
    liberado: validada,
    atualizarColunaNPara: validada ? 'OK - ASSINADO' : undefined,
  },
}];

// Monta e-mail (novo_pedido liberado) OU avalia cobrança (monitoramento).
// Produz um campo `acao` que o Switch seguinte usa pra rotear.

const MESES_ABREV_PT = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const MARCADOR_PROJETO = { REUNION: 'REUNION - PEDIDO DE NOTAS', SOFT_PRE: 'SOFT PRE - PEDIDO NOTAS', AREP: 'AREP - PEDIDO DE NOTAS' };

function somarDias(data, dias) { const d = new Date(data); d.setDate(d.getDate() + dias); return d; }
function diferencaDias(a, b) { const MS = 86400000; const u1 = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate()); const u2 = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()); return Math.round((u1 - u2) / MS); }
function formatarDataBR(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear(); }
function formatarDataCurta(d) { return String(d.getDate()).padStart(2,'0') + '.' + String(d.getMonth()+1).padStart(2,'0'); }
function normalizar(t) { return t ? String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim() : ''; }

function determinarTipoEmissao(descricao, projetoId) {
  const norm = normalizar(descricao);
  if (projetoId === 'AREP' && /\bpacote\b/.test(norm)) return 'PACOTE';
  if (/\brec\b.*\bnf\b|\bloca[cç][aã]o\b/.test(norm)) return 'REC_NF';
  if (/\bdi[aá]ria\b/.test(norm)) return 'DIARIA';
  if (/\bjob\b/.test(norm)) return 'JOB';
  return 'NF_NORMAL';
}
function extrairParcela(descricao) { const m = /\bP\.?\s*(\d+)\s*\/\s*(\d+)\b/i.exec(descricao || ''); return m ? ('P.' + m[1] + '/' + m[2]) : null; }
function montarRefAssunto(tipo, dataVenc, descricao) {
  const parcela = extrairParcela(descricao);
  if (tipo === 'JOB') return parcela ? ('REF. JOB (' + parcela + ')') : 'REF. JOB';
  if (tipo === 'DIARIA') return 'REF. DIÁRIA';
  if (tipo === 'PACOTE') return 'REF. PACOTE';
  if (tipo === 'REC_NF') return 'EMISSÃO DE NF E REC | REF. ' + MESES_ABREV_PT[dataVenc.getMonth()];
  return 'REF. ' + MESES_ABREV_PT[dataVenc.getMonth()];
}
function resolverApelidoAtual(apelidos, projetoId) {
  const lista = (apelidos && apelidos[projetoId]) || [];
  if (!lista.length) throw new Error('Sem apelido cadastrado para ' + projetoId);
  return lista[lista.length - 1];
}

const TOMADOR_HTML = 'Tomador<br>\nBOXFISH PRODUTORA DE PROGRAMAS TELEVISIVOS, INTERNET E FILMES PUBLICITÁRIOS LTDA.<br>\nEndereço: Rua Butantã, 194, sala 24, Pinheiros.<br>\nCEP 05.424-000 - São Paulo, SP<br>\nCNPJ: 14.788.649/0001-23<br>\nIM: 4.436.095-9<br>\nIE: ISENTA';
const AVISO_HTML = '<span style="background-color:#FFFF00;">"Os dados bancários considerados para pagamento são os que estão cadastrados.<br>\nO cadastro é feito baseado nas informações cedidas pelo contratado através do preenchimento de ficha cadastral da Box.<br>\nQualquer alteração bancária ou mudança na forma de pagamento deve ser notificada por e-mail pelo contratado e se faz necessário atualização da ficha cadastral e envio prévio ao responsável financeiro do projeto."</span>';

function montarCorpoEmailPedido(p) {
  const valorFmt = p.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const linhaServico = p.ehLocacao ? ('Locação: ' + p.servicoPrestadoComo) : ('Serviço Prestado como: ' + p.servicoPrestadoComo);
  return 'Olá ' + p.primeiroNome + '! Tudo bem?<br><br>\n' +
    'Seguem as instruções para a emissão da sua nota fiscal que deverá ser enviada até o dia ' + formatarDataBR(p.dataEnvio) + ' com vencimento em ' + formatarDataBR(p.dataVencimento) + '.<br><br>\n' +
    TOMADOR_HTML + '<br><br>\n' +
    '1- Emitir nota fiscal no valor de R$ ' + valorFmt + ' com os dados abaixo no corpo da nota:<br>\n' +
    'Ref. "' + p.textoRef + '"<br>\n' + linhaServico + '<br>\n' +
    'Colaborador: ' + p.nomeColaborador + '<br>\n' +
    (p.periodoTexto ? ('Período de ' + p.periodoTexto + '<br>\n') : '') +
    'Dados bancários:<br>\nChave pix:<br>\n---------------------------------------------------------------------<br><br>\n' +
    'Importante: Peço a gentileza de enviar a sua nota nestes e-mails:<br>\nfinanceiro@novorealitybox.com<br>\nfinanceiro1@novorealitybox.com<br><br>\n' +
    AVISO_HTML + '<br><br>\nMuito obrigada! Beijo 🌷';
}

function ehModoAutomatico(config) { return config && config.modo === 'automatico'; }

function decidirAcaoEnvio(gatilho, modoAutomatico) {
  if (!modoAutomatico) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  if (gatilho === 'SOLICITAR') return { acaoGmail: 'enviar_direto', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
  return { acaoGmail: 'agendar_envio', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
}

function avaliarCobranca({ hoje, dataProgramarAte, dataVencimentoNF, estadoAtual }) {
  if (estadoAtual && estadoAtual.encerrado) return { acao: 'nenhuma' };
  const fimDoCiclo = somarDias(dataVencimentoNF, -5);
  if (diferencaDias(hoje, dataProgramarAte) < 0) return { acao: 'nenhuma' };
  if (diferencaDias(hoje, fimDoCiclo) >= 0) {
    return { acao: 'encerrar_sem_resposta', novoEstado: { dataUltimaCobranca: estadoAtual ? estadoAtual.dataUltimaCobranca : null, contagemCiclos: estadoAtual ? estadoAtual.contagemCiclos : 0, encerrado: true } };
  }
  if (!estadoAtual) {
    const diaPrimeira = somarDias(dataProgramarAte, 1);
    if (diferencaDias(hoje, diaPrimeira) >= 0) {
      return { acao: 'cobrar', novoEstado: { dataUltimaCobranca: hoje.toISOString().slice(0,10), contagemCiclos: 1, encerrado: false } };
    }
    return { acao: 'nenhuma' };
  }
  const dataUltima = new Date(estadoAtual.dataUltimaCobranca);
  if (diferencaDias(hoje, dataUltima) >= 5) {
    return { acao: 'cobrar', novoEstado: { dataUltimaCobranca: hoje.toISOString().slice(0,10), contagemCiclos: estadoAtual.contagemCiclos + 1, encerrado: false } };
  }
  return { acao: 'nenhuma' };
}

const hoje = new Date();
const saida = [];

for (const item of $input.all()) {
  const d = item.json;

  if (d.fluxo === 'monitoramento') {
    const vencimento = new Date(d.nota.colunaG);
    const chaveCobranca = d.perfil.retranca + '_L' + d.nota.linha;
    const estadoAtual = d.cobrancas ? d.cobrancas[chaveCobranca] : undefined;
    // dataProgramarAte da nota original: não temos mais o texto 'PROGRAMAR ATÉ' (já virou SOLICITADA MI),
    // então usamos a data registrada em cobrancas.json na 1ª passagem; se não existir ainda, usamos hoje
    // como aproximação conservadora (evita cobrar cedo demais) — ver docs/spec.md 3.1.1.
    const dataProgramarAte = estadoAtual && estadoAtual.dataProgramarAteOriginal ? new Date(estadoAtual.dataProgramarAteOriginal) : hoje;
    const resultado = avaliarCobranca({ hoje, dataProgramarAte, dataVencimentoNF: vencimento, estadoAtual });
    saida.push({ json: { ...d, acao: resultado.acao === 'cobrar' ? (d.config.modo === 'automatico' ? 'cobrar_enviar' : 'cobrar_rascunho') : resultado.acao, chaveCobranca, novoEstadoCobranca: resultado.novoEstado } });
    continue;
  }

  // fluxo === 'novo_pedido'
  if (!d.liberado) {
    saida.push({ json: { ...d, acao: 'pendente_contrato' } });
    continue;
  }

  const partesDescricao = (d.nota.colunaJ || '').split(' - ');
  const cargo = partesDescricao[0] || '';
  const nomeColaborador = (partesDescricao[1] || d.nota.colunaH || '').trim();
  const primeiroNome = nomeColaborador.split(' ')[0] || nomeColaborador;
  const periodoTexto = partesDescricao.length >= 3 ? partesDescricao.slice(2).join(' - ') : '';

  const dataVencimento = new Date(d.nota.colunaG);
  const dataEnvio = d.gatilho === 'PROGRAMAR_ATE' ? new Date(new Date(d.dataProgramarAte)) : hoje;
  // prazo de envio = data ("PROGRAMAR ATÉ") + 5 dias — spec.md seção 3.1, 2º.
  const dataEnvioComPrazo = d.gatilho === 'PROGRAMAR_ATE' ? (function(){ const dd = new Date(dataEnvio); dd.setDate(dd.getDate()+5); return dd; })() : dataEnvio;

  const tipoEmissao = determinarTipoEmissao(d.nota.colunaJ, d.nota.projetoId);
  const ehLocacao = tipoEmissao === 'REC_NF';
  const refAssunto = montarRefAssunto(tipoEmissao, dataVencimento, d.nota.colunaJ);
  const apelidoAtual = resolverApelidoAtual(d.apelidos, d.nota.projetoId);

  const corpo = montarCorpoEmailPedido({
    primeiroNome, dataEnvio: dataEnvioComPrazo, dataVencimento,
    textoRef: d.perfil.texto_ref, valor: d.nota.colunaK,
    servicoPrestadoComo: cargo, nomeColaborador, periodoTexto, ehLocacao,
  });
  const assunto = apelidoAtual + ' | EMISSÃO DE NF | ' + refAssunto + ' (ENVIAR ATÉ ' + formatarDataCurta(dataEnvioComPrazo) + ') | ' + nomeColaborador;

  const decisao = decidirAcaoEnvio(d.gatilho, ehModoAutomatico(d.config));

  saida.push({
    json: {
      ...d,
      acao: decisao.acaoGmail,
      atualizarColunaL: decisao.atualizarColunaL,
      novoValorColunaL: decisao.novoValorColunaL,
      emailDestino: d.nota.colunaR,
      assunto,
      corpoHtml: corpo,
      marcadores: ['IA', MARCADOR_PROJETO[d.nota.projetoId]],
    },
  });
}

return saida;

// Consolida: (a) mudanças de coluna N/L a escrever no Box, (b) novo cobrancas.json, (c) itens pra alertar via Telegram (encerramento de ciclo sem resposta).

const itens = $input.all().map((i) => i.json);

const mudancasColunaN = itens
  .filter((d) => d.atualizarColunaNPara)
  .map((d) => ({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.atualizarColunaNPara }));

const mudancasColunaL = itens
  .filter((d) => d.atualizarColunaL && d.novoValorColunaL)
  .map((d) => ({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.novoValorColunaL }));

const cobrancasAtualizadas = { ...(itens[0] ? itens[0].cobrancas : {}) };
for (const d of itens) {
  if (d.chaveCobranca && d.novoEstadoCobranca) {
    cobrancasAtualizadas[d.chaveCobranca] = d.novoEstadoCobranca;
  }
}

const alertasEncerramento = itens.filter((d) => d.acao === 'encerrar_sem_resposta');
const rascunhosCriados = itens.filter((d) => d.acao === 'criar_rascunho' || d.acao === 'cobrar_rascunho');
const enviosDiretos = itens.filter((d) => d.acao === 'enviar_direto' || d.acao === 'cobrar_enviar');
const pendentesContrato = itens.filter((d) => d.acao === 'pendente_contrato');

return [{
  json: {
    mudancasColunaN,
    mudancasColunaL,
    cobrancasAtualizadas,
    resumo: {
      rascunhosCriados: rascunhosCriados.length,
      enviosDiretos: enviosDiretos.length,
      pendentesContrato: pendentesContrato.length,
      alertasEncerramento: alertasEncerramento.map((a) => ({ colaborador: (a.nota.colunaJ || '').split(' - ')[1] || a.nota.colunaH, projetoId: a.nota.projetoId })),
    },
  },
}];

// Aplica as mudanças de coluna N e L em memória (exceljs) e prepara o binário pra upload.
const ExcelJS = require('exceljs');

const mudancasN = $('Consolidar mudanças e cobrancas.json').first().json.mudancasColunaN;
const mudancasL = $('Consolidar mudanças e cobrancas.json').first().json.mudancasColunaL;

const item = $input.first();
const buffer = Buffer.from(item.binary.data.data, 'base64');
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);
const ws = wb.getWorksheet('Notas') || wb.worksheets[0];

for (const m of mudancasN) {
  ws.getCell('N' + m.linha).value = m.valor;
}
for (const m of mudancasL) {
  ws.getCell('L' + m.linha).value = m.valor;
}

const novoBuffer = await wb.xlsx.writeBuffer();
return [{
  json: {},
  binary: { data: { data: Buffer.from(novoBuffer).toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: 'cost_report_atualizado.xlsx' } },
}];
